// --- Normalisation categorie -> 6 poles canoniques (sync src/lib/blogCategories.ts) ---
function categoryToPole(raw) {
  var POLES = ['SEO & Visibilité','Publicité en ligne','Réseaux sociaux & Influence','E-commerce & Vente en ligne','IA & Automatisation','Business & Gestion'];
  if (!raw) return 'Business & Gestion';
  if (POLES.indexOf(raw) !== -1) return raw;
  var v = ' ' + String(raw).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim() + ' ';
  var map = [
    ['Publicité en ligne', ['publicite','ads','sponsoris','campagne pay','pub ']],
    ['SEO & Visibilité', ['seo','referencement','google my business','google business','google maps','visibilit','trafic organique']],
    ['IA & Automatisation', ['intelligence artificielle','automatis','chatgpt',' ia ']],
    ['Réseaux sociaux & Influence', ['reseaux sociaux','influence','community','personal brand','marque personnelle','social media','social','linkedin','instagram']],
    ['E-commerce & Vente en ligne', ['e-commerce','ecommerce','vente','vendre','paiement','logistique','catalogue','boutique','mobile money']],
    ['Business & Gestion', ['business','gestion','entrepreneur','finance','tresorerie','juridique','fiscalit','freelanc','carriere','salaire','outils','equipement','productivit']]
  ];
  for (var i=0;i<map.length;i++){
    for (var j=0;j<map[i][1].length;j++){ if (v.indexOf(map[i][1][j]) !== -1) return map[i][0]; }
  }
  return 'Business & Gestion';
}

// --- Conversion des liens internes [LIEN_INTERNE] -> <a href> (slugs réels uniquement) ---
function resolveInternalLinks(html, catalogue) {
  var slugs = {};
  (catalogue || []).forEach(function (a) { slugs[a.slug] = true; });
  return String(html || '').replace(/\[LIEN[_ ]INTERNE\s*:?\s*([^\]]*?)\]/gi, function (_m, body) {
    var parts = body.split(/→|->/);
    var text = (parts[0] || '').trim();
    var url = (parts[1] || '').trim();
    var ok = url === '/formations' || url === '/mon-espace';
    var m = url.match(/^\/blog\/(.+)$/);
    if (m && slugs[m[1]]) ok = true;
    return ok ? '<a href="' + url + '">' + text + '</a>' : text;
  });
}

const response = $input.item.json;
const inputData = $('Parse — Données recherche').item.json;

// Extract raw text from Gemini response (multiple possible formats)
let rawText = '';
if (response.content?.parts) {
  rawText = response.content.parts.map(p => p.text || '').join('');
} else if (response.candidates?.[0]?.content?.parts) {
  rawText = response.candidates[0].content.parts.map(p => p.text || '').join('');
} else if (typeof response === 'string') {
  rawText = response;
} else if (response.title || response.content_html) {
  // Already parsed
  rawText = JSON.stringify(response);
}

// Robust JSON extraction : handles markdown fences + trailing text
function extractJson(text) {
  if (!text) return null;

  // 1. Remove markdown code fences
  let cleaned = text.trim();
  cleaned = cleaned.replace(/^```(?:json)?\s*\n?/i, '').replace(/\n?```\s*$/i, '').trim();

  // 2. Try direct parse
  try { return JSON.parse(cleaned); } catch(e) {}

  // 3. Find first { and try to parse balanced JSON
  const start = cleaned.indexOf('{');
  if (start === -1) return null;

  // Walk the string to find the matching closing brace (ignoring strings)
  let depth = 0;
  let inString = false;
  let escape = false;
  for (let i = start; i < cleaned.length; i++) {
    const c = cleaned[i];
    if (escape) { escape = false; continue; }
    if (c === '\\') { escape = true; continue; }
    if (c === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (c === '{') depth++;
    else if (c === '}') {
      depth--;
      if (depth === 0) {
        const candidate = cleaned.substring(start, i + 1);
        try { return JSON.parse(candidate); } catch(e) {
          // Keep trying — maybe truncated
        }
      }
    }
  }

  // 4. Last resort : regex for first balanced-looking block
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { return JSON.parse(match[0]); } catch(e) {}
  }

  return null;
}

let article = extractJson(rawText);

if (!article) {
  // Truncated/invalid Gemini output → skip this row rather than crash workflow
  return [];
}

const now = new Date().toISOString();
const slug = (article.suggested_slug || article.title || '')
  .toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 80);

const blogPost = {
  title: article.title || inputData.subject,
  slug: slug,
  excerpt: article.excerpt || article.meta_description || '',
  content: resolveInternalLinks(article.content_html || '', inputData.articles_catalogue || []),
  coverImage: '',
  category: categoryToPole(article.category),
  tags: article.tags || [],
  author: 'Max-Morrys',
  publishedAt: now,
  readTime: article.reading_time_minutes || Math.ceil((article.word_count || 1500) / 200),
  featured: false,
  status: 'draft',
  metaTitle: article.title || '',
  metaDescription: article.meta_description || '',
  focusKeyword: inputData.main_keyword || '',
  ogTitle: article.title || '',
  ogDescription: article.meta_description || '',
  ogImage: '',
  twitterTitle: article.title || '',
  twitterDescription: article.meta_description || '',
  twitterImage: '',
  noIndex: false,
  createdAt: now,
  id: inputData.id
};

return {
  json: {
    blogPost,
    type: 'article',
    slug: slug,
    prompt: article.featured_image_prompt || ('Image de couverture pour article: ' + blogPost.title),
    dimensions: '1920x1080',
    context: 'Article blog marketing digital Afrique de l\'Ouest',
    for_workflow: 'wf08',
    featured_image_prompt: article.featured_image_prompt || '',
    internal_links: article.internal_links || [],
    faq: article.faq || [],
    word_count: article.word_count || 0,
    id: inputData.id
  }
};

// runOnceForEachItem
const input = $input.item.json;
return {
  json: {
    prompt: input.featured_image_prompt || ('Image de couverture pour article: ' + (input.blogPost?.title || 'article')),
    dimensions: '1920x1080',
    type: 'article',
    context: 'Article blog marketing digital Afrique de l\'Ouest',
    for_workflow: 'wf08',
    slug: input.blogPost?.slug || '',
    blogPost_passthrough: input.blogPost,
    id: input.id
  }
};

