// runOnceForEachItem
const input = $input.item.json;
const originalData = $('IMG1 — Normaliser — Input').item.json;

let enhancedPrompt = originalData.prompt;

try {
  let text = '';
  if (input.content?.parts) {
    text = input.content.parts.map(p => p.text || '').join('');
  } else if (typeof input === 'string') {
    text = input;
  } else if (input.text) {
    text = input.text;
  }
  if (text) {
    const jsonMatch = text.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const parsed = JSON.parse(jsonMatch[0]);
      if (parsed.enhanced_prompt) enhancedPrompt = parsed.enhanced_prompt;
    }
  }
} catch(e) {}

if (!enhancedPrompt || !enhancedPrompt.trim()) {
  enhancedPrompt = originalData.prompt;
}

return {
  json: {
    prompt: enhancedPrompt,
    original_prompt: originalData.prompt,
    type: originalData.type,
    dimensions: originalData.dimensions,
    context: originalData.context,
    for_workflow: originalData.for_workflow,
    slug: originalData.slug,
    id: originalData.id,
    blogPost_passthrough: originalData.blogPost_passthrough
  }
};

